"""Golden byte digest generated by the original S2 chunker at f5ce43c."""

import hashlib
import json
from dataclasses import asdict
from pathlib import Path

from docguard.processing.chunker import chunk_document
from docguard.processing.config import load_chunking_config
from docguard.processing.models import DocumentRecord, SectionBlock, make_document_id
from docguard.processing.token_budget import TokenBudget


def test_postgresql_chunk_records_remain_byte_identical_to_pre_s15():
    root = Path(__file__).resolve().parents[2]
    config = load_chunking_config(root / "configs/chunking/s2-chunk-v1.json")
    budget = TokenBudget.from_manifest(root / "data/tokenizers/manifest.json", root)
    url = "https://www.postgresql.org/docs/17/sql-select.html"
    document = DocumentRecord(
        make_document_id("17.11", url), "17.11", "sql_commands", url, "SELECT", "a" * 64
    )
    blocks = [
        SectionBlock(
            "paragraph",
            "intro",
            ("SELECT", "Description"),
            "PostgreSQL SELECT retrieves rows from a table. " * 180,
        ),
        SectionBlock(
            "code",
            "code",
            ("SELECT", "Syntax"),
            "\n".join("SELECT value FROM sample_table;" for _ in range(60)),
        ),
        SectionBlock(
            "table",
            "options",
            ("SELECT", "Options"),
            "Option | Description\n"
            + "\n".join(f"option_{i} | explanation of option {i}" for i in range(100)),
        ),
    ]
    records = chunk_document(document, blocks, config, budget)
    payload = json.dumps(
        [asdict(r) for r in records], ensure_ascii=False, sort_keys=True
    ).encode()
    assert len(records) == 13
    assert (
        hashlib.sha256(payload).hexdigest()
        == "c129acb00123893e0f01d2f0dd74d63d51d6a227feb59e5ba61c9b53af16ecda"
    )


def test_long_code_line_keeps_whitespace_and_repeated_explanation():
    from docguard.knowledge.models import Block
    from docguard.processing.block_packer import _split_block

    root = Path(__file__).resolve().parents[2]
    budget = TokenBudget.from_manifest(root / "data/tokenizers/manifest.json", root)
    explanation = "The following example writes a JSON object."
    line = "\t" + '{"value": "a  b", "array": [1, 2, 3]}, ' * 160
    fragments = _split_block(
        Block("code", "json", ("IO tools", "JSON"), line),
        explanation=explanation,
        budget=budget,
        maximum=384,
    )
    assert len(fragments) > 1
    assert all(fragment.text.startswith(explanation + "\n\n") for fragment in fragments)
    assert (
        "".join(fragment.text[len(explanation) + 2 :] for fragment in fragments) == line
    )
    assert all(
        budget.count("IO tools > JSON\n\n" + fragment.text) <= 384
        for fragment in fragments
    )


def test_oversized_explanation_stays_in_its_own_chunks_without_blocking_code():
    from docguard.knowledge.models import Block
    from docguard.processing.block_packer import pack_blocks

    root = Path(__file__).resolve().parents[2]
    budget = TokenBudget.from_manifest(root / "data/tokenizers/manifest.json", root)
    config = load_chunking_config(root / "configs/chunking/s2-chunk-v1.json")
    explanation = "Detailed explanation of JSON serialization behavior. " * 120
    line = '{"a": 1, "b": 2},' * 160
    blocks = (
        Block("paragraph", "json", ("JSON",), explanation),
        Block("code", "json", ("JSON",), line),
    )
    records = pack_blocks(blocks, config, budget)
    assert records
    assert all(record.token_count <= config.max_chunk_tokens for record in records)
    assert any("Detailed explanation" in record.text for record in records)
    assert any('{"a": 1' in record.text for record in records)
